import{_ as t,o as e,c as s,a0 as i}from"./chunks/framework.DqMqoJl9.js";const u=JSON.parse('{"title":"安装 NATS","description":"","frontmatter":{},"headers":[],"relativePath":"guides/install-nats.md","filePath":"guides/install-nats.md"}'),n={name:"guides/install-nats.md"};function r(o,a,l,d,h,c){return e(),s("div",null,[...a[0]||(a[0]=[i('<h1 id="安装-nats" tabindex="-1">安装 NATS <a class="header-anchor" href="#安装-nats" aria-label="Permalink to &quot;安装 NATS&quot;">​</a></h1><p>NATS 是 Cherry 集群模式的节点间通信中间件。<strong>单机模式（Standalone）不需要安装</strong>。</p><h2 id="什么时候需要" tabindex="-1">什么时候需要 <a class="header-anchor" href="#什么时候需要" aria-label="Permalink to &quot;什么时候需要&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>是否需要 NATS</th></tr></thead><tbody><tr><td>单节点开发（<code>cherry.Standalone</code>）</td><td>不需要</td></tr><tr><td>多节点集群（<code>cherry.Cluster</code>）</td><td>需要</td></tr><tr><td><a href="/examples/demo-chat.html">单节点聊天室</a></td><td>不需要</td></tr><tr><td><a href="/examples/demo-cluster.html">多节点集群</a></td><td>需要</td></tr><tr><td>使用 <a href="/core/etcd.html">etcd 发现服务</a> 的集群</td><td>需要（集群通信仍走 NATS）</td></tr></tbody></table><h2 id="任选一种安装方式" tabindex="-1">任选一种安装方式 <a class="header-anchor" href="#任选一种安装方式" aria-label="Permalink to &quot;任选一种安装方式&quot;">​</a></h2><h3 id="项目自带-windows-最省事" tabindex="-1">项目自带（Windows，最省事） <a class="header-anchor" href="#项目自带-windows-最省事" aria-label="Permalink to &quot;项目自带（Windows，最省事）&quot;">​</a></h3><p>示例仓库里已经放了一份 Windows 版可执行文件：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>examples/3rd/nats-server/nats-server.exe</span></span></code></pre></div><p>直接双击运行即可。</p><h3 id="官方安装指南" tabindex="-1">官方安装指南 <a class="header-anchor" href="#官方安装指南" aria-label="Permalink to &quot;官方安装指南&quot;">​</a></h3><p><a href="https://docs.nats.io/running-a-nats-service/introduction/installation" target="_blank" rel="noreferrer">https://docs.nats.io/running-a-nats-service/introduction/installation</a></p><h3 id="docker" tabindex="-1">Docker <a class="header-anchor" href="#docker" aria-label="Permalink to &quot;Docker&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 4222:4222</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nats:latest</span></span></code></pre></div><p>或参考：<a href="https://docs.nats.io/running-a-nats-service/introduction/installation#installing-via-docker" target="_blank" rel="noreferrer">https://docs.nats.io/running-a-nats-service/introduction/installation#installing-via-docker</a></p><h3 id="安装包下载" tabindex="-1">安装包下载 <a class="header-anchor" href="#安装包下载" aria-label="Permalink to &quot;安装包下载&quot;">​</a></h3><p><a href="https://github.com/nats-io/nats-server/releases" target="_blank" rel="noreferrer">https://github.com/nats-io/nats-server/releases</a></p><h3 id="homebrew" tabindex="-1">Homebrew <a class="header-anchor" href="#homebrew" aria-label="Permalink to &quot;Homebrew&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">brew</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nats-server</span></span></code></pre></div><h2 id="验证服务" tabindex="-1">验证服务 <a class="header-anchor" href="#验证服务" aria-label="Permalink to &quot;验证服务&quot;">​</a></h2><p>启动后窗口显示下面的内容代表启动成功：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Listening for client connections on 0.0.0.0:4222</span></span></code></pre></div><p>默认监听 <code>4222</code> 端口，与 Cherry 默认配置里的 <code>nats://127.0.0.1:4222</code> 一致。</p><div class="warning custom-block"><p class="custom-block-title">正式环境请用集群部署</p><p>单机 NATS 一旦挂掉，整个集群就失去通信能力。生产环境请部署 NATS 集群，至少 3 个节点。</p></div>',23)])])}const b=t(n,[["render",r]]);export{u as __pageData,b as default};
